  /** helper function to check AccessCoherence_supervisor_process_access_coherence's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param recovery_transition method that will be called with the value of the outgoing data
   *        port 'recovery_transition'.
   * @param admission_guard method that will be called with the value of the outgoing data
   *        port 'admission_guard'.
   * @param lifecycle_frame method that will be called with the value of the outgoing data
   *        port 'lifecycle_frame'.
   * @param berth_transition_evidence method that will be called with the value of the outgoing data
   *        port 'berth_transition_evidence'.
   * @param gate_safety_frame method that will be called with the value of the outgoing data
   *        port 'gate_safety_frame'.
   * @param docking_frame method that will be called with the value of the outgoing data
   *        port 'docking_frame'.
   * @param access_frame method that will be called with the value of the outgoing data
   *        port 'access_frame'.
   * @param undocking_frame method that will be called with the value of the outgoing data
   *        port 'undocking_frame'.
   * @param priority_directive method that will be called with the value of the outgoing data
   *        port 'priority_directive'.
   */
  def check_concrete_output(recovery_transition: Docking_Access_Supervisor.RecoveryTransition => B,
                            admission_guard: Docking_Access_Supervisor.AdmissionGuard => B,
                            lifecycle_frame: Docking_Access_Supervisor.CoordinationFrame => B,
                            berth_transition_evidence: Docking_Access_Supervisor.BerthTransitionEvidence => B,
                            gate_safety_frame: Docking_Access_Supervisor.GateSafetyFrame => B,
                            docking_frame: Docking_Access_Supervisor.CoordinationFrame => B,
                            access_frame: Docking_Access_Supervisor.CoordinationFrame => B,
                            undocking_frame: Docking_Access_Supervisor.CoordinationFrame => B,
                            priority_directive: Docking_Access_Supervisor.PriorityDirective => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val recovery_transitionValue: Docking_Access_Supervisor.RecoveryTransition = get_recovery_transition().get
    if(!recovery_transition(recovery_transitionValue)) {
      testFailures = testFailures :+ st"'recovery_transition' did not match expected: value of the outgoing data port is ${recovery_transitionValue}"
    }
    val admission_guardValue: Docking_Access_Supervisor.AdmissionGuard = get_admission_guard().get
    if(!admission_guard(admission_guardValue)) {
      testFailures = testFailures :+ st"'admission_guard' did not match expected: value of the outgoing data port is ${admission_guardValue}"
    }
    val lifecycle_frameValue: Docking_Access_Supervisor.CoordinationFrame = get_lifecycle_frame().get
    if(!lifecycle_frame(lifecycle_frameValue)) {
      testFailures = testFailures :+ st"'lifecycle_frame' did not match expected: value of the outgoing data port is ${lifecycle_frameValue}"
    }
    val berth_transition_evidenceValue: Docking_Access_Supervisor.BerthTransitionEvidence = get_berth_transition_evidence().get
    if(!berth_transition_evidence(berth_transition_evidenceValue)) {
      testFailures = testFailures :+ st"'berth_transition_evidence' did not match expected: value of the outgoing data port is ${berth_transition_evidenceValue}"
    }
    val gate_safety_frameValue: Docking_Access_Supervisor.GateSafetyFrame = get_gate_safety_frame().get
    if(!gate_safety_frame(gate_safety_frameValue)) {
      testFailures = testFailures :+ st"'gate_safety_frame' did not match expected: value of the outgoing data port is ${gate_safety_frameValue}"
    }
    val docking_frameValue: Docking_Access_Supervisor.CoordinationFrame = get_docking_frame().get
    if(!docking_frame(docking_frameValue)) {
      testFailures = testFailures :+ st"'docking_frame' did not match expected: value of the outgoing data port is ${docking_frameValue}"
    }
    val access_frameValue: Docking_Access_Supervisor.CoordinationFrame = get_access_frame().get
    if(!access_frame(access_frameValue)) {
      testFailures = testFailures :+ st"'access_frame' did not match expected: value of the outgoing data port is ${access_frameValue}"
    }
    val undocking_frameValue: Docking_Access_Supervisor.CoordinationFrame = get_undocking_frame().get
    if(!undocking_frame(undocking_frameValue)) {
      testFailures = testFailures :+ st"'undocking_frame' did not match expected: value of the outgoing data port is ${undocking_frameValue}"
    }
    val priority_directiveValue: Docking_Access_Supervisor.PriorityDirective = get_priority_directive().get
    if(!priority_directive(priority_directiveValue)) {
      testFailures = testFailures :+ st"'priority_directive' did not match expected: value of the outgoing data port is ${priority_directiveValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


